INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1498459-mis101', 'stk-user9840', 'MIS 101', 'info', '{"desc": "هذا الموضوع مخصص لمناقشة المقرر المذكور في العنوان\nبنود تساعد في تقييم المقرر:\n\nجودة المقرر بشكل عام\nالمواضيع التي يغطيها المقرر\nالكتاب المستخدم للمقرر\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\n\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\n\nكما نرجو تحري الصدق والعدل في تقييم المقرر\nوعدم الخلط بين تقييم الأستاذ وتقييم المقرر بذاته\n\n(Introduction to business computing concepts. Topics include business applications and problem solving using high-level programming languages; development of web-based and mobile applications; use of business software with emphasis on database queries and reports; spreadsheet and financial and statistical functions. Concepts are reinforced through practical exercises from real world domains.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-101-business-computing/180011/1", "user": "user9840", "ts": 1535676775000, "tid": 180011, "pn": 1}}', 1535676775000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_d7omk13-mis101', 'stk-_d7omk13', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS-101 Term-191\nالتحضير: غالبا يحضر وغالبا لا بس هو يناظر في الكلاس ويشوف عدد الطلاب الحاضرين.\nالشرح: شرحه ممتاز مررة يشرح على سلايدات وهي الي تذاكر منها عشان الكوزات والمد والفاينل و شرحه يكون مرتب وتخرج وانت فاهم.\nالكوزات: سهلة تكون اختيارات غالبا أو صح و خطأ.\nالمياجر و الفاينلات: سهلة بس يبغالك تذاكر السلايدات الي يرفعها على البلاك بورد وأمورك تمام.\nالقريد النهائي: A+++++++ إذا لقيته نزل عنده وانت مغمض وراح تضمن قريد عالي إن شاء الله.\nالصوت: واضح جدا والاكسنت واضح.\nإضافات: الدكتور أخلاق مرة ماشاء الله يحاول يساعدك قد مايقدر ومايتعب الطلاب مرة ومتعاون في الساعات المكتبية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518515-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/40", "user": "_D7omk13", "ts": 1577799480000, "tid": 98441, "pn": 40}}]}', 1577799480000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_h-mis101', 'stk-ali_h', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : إيهاب قحوش\nالمادة: mis 101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : لا يوجد تحضير بس يبقاك تحضر يوم الاب عشان يحط لك درجة ع اللاب\nطريقة الشرح : ممتاز جدا و خفيف\nالكويزات : سهلة مرة\nالمياجر: سهلة و بسيطة\nالفاينلات : سهل مرة\nالقريد النهائي:A\nالصوت: واضح جدا و الاكسنت حقه تمام\nإضافات :\n١- الدكتور تعامل ممتاز جدا جدا متساهل\n٢- في التصحيح المياجر كان شوي شديد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518694-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/41", "user": "Ali_h", "ts": 1578120176000, "tid": 98441, "pn": 41}}]}', 1578120176000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-mis101', 'stk-khdsa2022', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : ايهاب قحوش\nالمادة: MIS 101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : مايحضر\nطريقة الشرح : اسطووووورة ويكرف بس كرفه عسل\nالكويزات : تاااافه وسهلة\nالمياجر: الميد تااافه لو تذاكر بس ساعة\nالفاينلات : تااافه نفس الميد\nالقريد النهائي: A+\nالصوت: ممتاز واكسنت سوري او اردني\nإضافات :الدكتور عسل لاتفوته ابد وتراه رفعنا قريد كامل في النهاية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518835-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/42", "user": "Khdsa2022", "ts": 1578294910000, "tid": 98441, "pn": 42}}]}', 1578294910000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-mis101', 'stk-nawafmkz', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ehab - Mis101 - 192\nالتحضير : نادراً أو برفع الاسايمنت في يوم اللاب\nطريقة الشرح : يشرح بشكل عام فكرة الدرس وتطبيقاته في البزنس والتخصصات الإدارية، إذا كان الشرح لشي عملي مثل الاكسل ينصح الطلاب يسجلون ملاحظات من اللي يقوله. بعدها تحل الاسايمنت وترفعه على الBB\nالكويزات : كويزات خفيفة كل واحد عليه بين الدرجة والدرجتين، يرسل ملف أو مقطع ويقول ذاكروا منه.\nالمياجر: لايوجد. ميدترم عملي (اكسل) ومشروعين اكسل و Access. وريبورت وبرزينتيشين.\nالفاينلات : لا يوجد في 192 (كورونا)\nالقريد النهائي: A+\nالصوت:ممتاز والاكسنت واضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525350-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/43", "user": "NawafMKZ", "ts": 1599247529000, "tid": 98441, "pn": 43}}]}', 1599247529000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-mis101', 'stk-guest', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS101-201\n\nالتحضير :\nطريقة الشرح :\nفي البداية يجيب سلايدات ويشرح للجزء النظري وبعدين يبدأ في التطبيقي ويوريك بالضبط كيف تسوي كل خطوة ويعيدها لو واحد ما فهمها وبعدين يطلب منك تسوي اسايمنت مشابهة لها في اللاب. وغالبًا نخلص قبل بدري قبل بنص ساعة وممكن أكثر(لكن في النهاية مع الاكسس صار يأخذ وصت أجثر لكن يظل نخلص قبل نهاية الوقت)\n\nالكويزات :\nسهلة وواضحة صح وخطأ من ملفات بسيطة يعطيك إياها قبل\n\nالمياجر:\nلو مركز معه في اللاب فالاختبار ما يصعب عليك وبالعكس يعتبر سهل. وكل الأسئلة اختيارات\n\nالفاينلات :\nنفس الكلام حق المياجر\n\nالقريد النهائي:\nA++ ولو فيه أهلى عطيته\nالصوت:\nواضح جدًا يشرع بالعربي والإنجليزي\nإضافات :\nأسطوري بكل ما تعينه الكلمة من كل النواحي، سواء التواصل معه في الواتس وسرعة ردوده أو في تفهمه لما تواجه مشكلة أو في شرحه وتبسيطه. يعني اللاب تشوف وقته تقول طويل لكن معه دايم جميل وما تتطفش بسرعة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527605-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/45", "user": "Guest", "ts": 1609841723000, "tid": 98441, "pn": 45}}]}', 1609841723000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_of_rivia-mis101', 'stk-m_of_rivia', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS 101 - 201\nالاسطورة ايهاب قحوش.\n\nالتحضير : ماقد حضر بالاسماء بس يشوف العدد وينتظر لين يكتمل العدد ويبدا اللاب.\n\nطريقة الشرح : المادة مالها كتاب فا الدكتور يجيب مصادر من عنده مثل سلايدات هو مسويها او مواقع الخ… شرحه ممتاز وواضح يعلمنا عن الموضوع بشكل عام بعدين يطبق قدامنا ثم يعطينا زي الاسايمنت سهل مره.\n\nالكويزات : عطانا تقريبا 6 كويزات واخذ افضل 5 منهم ، سهلين مره صح وخطا واحيانا خيارات . طبعا يعطينا كذا ملف خفيف لو تقراه بس تقدر تجيب فل.\nوفيه 2 بروجكت يوزع الطلاب مجموعات تقريبا من 3 الى 5 طلاب كل مجموعة.\n\nالمياجر: ميد سهل لو كنت فاهم الاسايمنتات.\nالفاينلات : نفس الميد.\n\nالقريد النهائي: A+ ولو فيه اكثر عطيته بالراحة.\nالصوت: عربي وانقليزي واضح جدااا.\nإضافات : الدكتور ايهاب من افضضل الدكاترة بالكلية اذا مو بالجامعة ، انصح اي واحد بيدرس mis 101 ينزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527915-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/46", "user": "M_of_Rivia", "ts": 1610804634000, "tid": 98441, "pn": 46}}]}', 1610804634000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-mis101', 'stk-sadguts', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f172139", "n": "Dr. Mohammed Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS101- 192\nالتحضير : كل يوم بدايه الكلاس ويحط ليت\nالشرح : يشرح لك ايش يبغى مع ان شرحه مو قد كذا لكن الماده بسيطه يحط روابط اونلاين وتقدر تفهم منها\nالكويزات : صعبه ويحطها صعبه عمدا عشان ينزل الافرج\nالمياجر : متوسطه الى سهله\nالصوت : لغته تعبانه لكن اذا تورط يتكلم عربي\nاضافات : لاتنزل الكورس عنده الا اذا مافي الا هو معقد الكورس وهو جدا سهل وطلباته غبيه مادري ايش يبغى بالضبط مابغى اظلمه للامانه لكن الشباب الي اخذوا الكورس عند دكتور ثاني جدا الشرح اوضح والوضع اسهل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521783-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammed-al-subaie/172139/4", "user": "SadGuts", "ts": 1588674950000, "tid": 172139, "pn": 4}}]}', 1588674950000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed13579-mis101', 'stk-ahmed13579', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f172139", "n": "Dr. Mohammed Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS101-201 online\nالتقييم :\nأول شي اسمه محمد السبيعي متخرج من الجامعة بكالوريوس mis وتوظف في ارامكو ثم طلع كمل دراسته وأخذ الماجستير ورجع يدرس في الجامعة.\nنبدأ في الكويزات :\nصعبة وبدون رجوع للسؤال السابق ( backtracking ) + دائمًا الناس تقول مقولة فهم السؤال نصف الإجابة وللأسف المدرس ذا ما يعرف انجليزي فيحط لك سؤال بخدعة ( trick ) محد يقدر يفهم السؤال إلا هو بسبب انجليزيته التعبانة + الوقت مو كافي ابد ابد حتى لو كان اونلاين واختيارات يعطيك ١٠ أسئلة في ٨ دقائق بدون رجوع للسؤال الي قبل + يحط أصغر خط موجود في البلاك بورد وكلمناه كبر الخط ما رضى قال لنا يمديك تسوي زوم بس ذا مو مبرر لك تتخيل يحط لك سؤال كأنه مقال ( essay ) وتركات عبيطه محد يفهمها.\n\nبتقول لي غيبة ؟ أقول لك إذا ما جربت اسكت هذا المدرس حتى ال labs محد جاب عنده فل الكل ناقص\n\nنجي لل labs : سهله لكن يدقق عليها وسهولتها بتسبب لك مشاكل في الاختبار النصفي ( midterm ) لأن الي بتاخذه شي والي بجيك شي ثاني\n\nنجي لل midterm : جاب لنا اشياء مختلفة عن اللابات + حتى جاب لنا أشياء ما اخذناها\n\nنجي لل projects : يحط لك ملف word فيه المتطلبات وفيها اشياء محد قادر يفهمها وتعليمات تحتاج لتعليمات عشان تفهمها واشياء غلط بغلط\n\nنجي للشرح : اعطيه صفر من عشرة والسبب دراسته بالانجليزي فهو حافظ المصطلحات بالانجليزي وبالتالي إذا توهق وجاء يبغا يشرح بالعربي ما يقدر + انجليزيته صفرررررررررر من عشرة القواعد عنده ( grammar ) مضروب وسيئ مرة ولا هو فاهم شغله ولا علمنا مثل الناس\n\nنجي للنهائي (final ) : هو الحسنه الوحيده لأن كان ٨٠٪ منه مثل الاختبارات القصيرة ( quizzes ) بس يظل فيه اسئلة ما بتفهمها والله ثم والله محد جاب فل لا في النهائي ولا النصفي وذا دليل على أنه سيئ بسبب أن كل الطلاب مو فاهمين عليه\n\nبتقول لي انجليزيتك ضعيفة أقول لك جايب في انجليزي التحضيري والجبل قريد b أو b+ وما نزلت عنهم أبد وهو المدرس الوحيد الي للحين مو قادر افهم عليه + افرج الطلاب ( ثلاث شعب ) كان حول ٧٨ والسبب أنه عالي لأننا كطلاب تعاونا مع بعض عشان نخلص المادة السهلة الي معقدها لنا بينما كان افرج طلاب ايهاب ٨٩ ،،، تعرف معنى ٨٩ ؟ ذي كانت اقل درجة لل A+ عند السبيعي\n\nكل الطلاب ناقصين عنده واذا تخصصك mis لا تدرس عنده أبد لأنك بتكره التخصص يسببه وهذا وضعي حاليا\n\nبالنسبة لوضعنا قبل ما نسجل عنده كانوا الطلاب يمدحوه بس لما درسنا عنده شفنا العكس تماما وما أنصحكم فيه ابد حتى لو المادة كريدت واحد ولا فيه بونص ولا شي ولا فيه backtracking ابدا ابدا حتى في الفاينل والميد وينقص في المشاريع بدون اسباب مثل الناس\n\nميزته حاجتين وهي الفاينل مثل ما قلت فوق + يرد بسرعة على ايميلاته\n\nقريدي معاه A+ لكن جبتها بتعبي ولا استفدت منه شي أبد وقارنا كطلاب طلاب السبيعي بطلاب ايهاب وشفنا طلاب ايهاب فاهمين اكثر وتعلموا اشياء اكثر مننا بكثير\n\nتقيمي النهائي له صفر من عشرة ولو فيه تقييم بالسالب راح اقيمه بالسالب عادي هذا كان اسوء مدرس مر علي من الابتدائي الى الجامعة هذا رقم واحد\n\nالي يقول لي تبالغ وغيبة وكذا وكذا أقول لك دامك ما جربت اسكت ،،، رحم الله والديك متى صارت كلمة الحق غيبة ؟ والي ما بصدق بكيفه روح ادرس عنده ولما تخلص الكورس بتشوف ان كلامي جد\n\nوراح تشوفوا بإذن الله تقييمات الطلاب المدرس ذا وتشوفوا كيف أنه جد سيئ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527746-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammed-al-subaie/172139/7", "user": "Ahmed13579", "ts": 1610262723000, "tid": 172139, "pn": 7}}]}', 1610262723000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_kn-mis101', 'stk-saleh_kn', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f172139", "n": "Dr. Mohammed Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS101 - 201 online\n\nالتحضير : يحضر بداية الكلاس ويحط ليت للي يجي ليت\n\nطريقة الشرح : عن نفسي كنت أركز معه وكان شرحه يجي منه وأفهم أغلب النقاط وبرضو اللابات كانت سهلة نسبيًا ف ما تحتاج شرح كثير\n\nالكويزات : اختبرنا 5 وأخذ أفضل 4… الأول كان مقالي ومعطينا وقت مرة قليل مقارنة بعدد ونوع الأسئلة!!!! صعب انك تاخذ كامل عنده وأسئلته كان فيها أخطاء في القرامر تعفس عليك فهم السؤال\n\nالمياجر: اختبرنا ميد واحد وكان متوسط الصعوبة وجاب لنا كم سؤال عن أشياء ما درسناها\n\nالفاينل : للأمانة كان سهل وكان أغلبه من الكويزات\n\nالقريد النهائي: أعطيه C+\n\nالصوت: واضح إذا كان النت عنده كويس، بالنسبة لكلاسي كان الخميس وكان النت عنده في أغلب المحاضرات كويس\n\nإضافات : الدكتور هذا غرررررررريييييببب مرة، ما يطول كلاساته ويرد على الأسئلة ويرد على ايميلاته بسرعة، لكن اختباراته صعبة وتحسه يتحدى الطلاب انهم يجيبون كامل مع ان المادة كريديت واحد واللي قبلنا وطلاب قحوش يقولون سهلة لكنه معقدها لنا كثير\nنصييييييحة إذا كلاسات قحوش مفتوحة روح عنده لو الساعة 10 الليل، كل الي درسوا عنده يمدحونه كشرح وأسلوب وتعامل ولغة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527757-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammed-al-subaie/172139/9", "user": "Saleh_KN", "ts": 1610278844000, "tid": 172139, "pn": 9}}]}', 1610278844000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-mis101', 'stk-jafar_15', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f180467", "n": "Dr. Jongtae Yu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS 101 - 182 & MIS 301 - 181\n\nالتحضير :\nفي 301 تحضيره كان عن طريق اسايمنت يعطينا اياه نهاية كل كلاس ومب كل الكلاسات فيها اسايمنت فيكون مافيها تحضير ، وفي 101 تحضيره عن طريق التاسكات اللي نرسلها بالبلاكبورد\n\nطريقة الشرح :\nشرحه وسط ويحاول يفهم الطالب بقدر مايستطيع ويجاوب على الاسئلة ومتساعد جدًا.\nفي 301 يستخدم سلايدات الكتاب ويشرح عليها ، في 101 كان يستخدم نوت يطبعه ويجيبه للطلاب ويطلب منا نسوي التمرينات اللي في النوت، ومرات يستخدم سلايدات من عنده. الشغل كان كله في اللاب ، حتى الكلاس العادي سواه في اللاب. لانه المادة practical اكثر من انها theoretical.\n\nالكويزات :\n101 ماكان في كويزات. في 301 كانت كويزاته MCQ سهلة الى متوسطة الصعوبة. اعطانا 6 كويزات اذا ماكنت غلطان وحذف اسوأ واحد\n\nالمياجر:\n101: المفترض كان ميجيرين ، ميجر على excel والثاني على access، لكن بعد درجات ميجر الاكسل كانت الدرجات مش ولابد فاعتبره مد ترم وعدل درجته وصارت من 20.\nالاختبار مقسم الى قسمين قسم تطبيقي على الاكسل ، وقسم كتابي تكتب functions حق عملية معينة مثل كيف تحسب الافرج ، كيف تسوي if statement. عطانا ملف اكسل وطلب نسوي بعض functions اللي اخذناها ونسوي visualizing حق جزء من البيانات اللي عندنا ، pie chart وغيره وطلب منا نسوي Pivot Table. وكان الميجر ماكان صعب ابدًا، لكن المشكلة من الطلاب انهم كانوا يستسهلون المادة بشكل كبير وماياخذونها بشكل جدي.\n\n301: كانت خليط بين MCQ و مقالي. جزء MCQ كان مشابه للكويزات ، والمقالي ماكان صعب ابدًا. سهل الى متوسط الصعوبة. اعطانا سيناريو وطلب منا نسوي له ERD وDFD\n\nالفاينلات :\n101: كان عن برنامج Access ، ونفس الفكرة مقالي وعلى الاكسس بالكمبيوتر. الجزء المقالي اعطانا سيناريو معين وطلب نسوي ERD للسيناريو نفسه ، وبعدين نسوي الجداول وquery بلغة SQL ونكتبهم في الورقة وبعدين تسويهم في ملف access وترفعه بالبلاكبورد\nالجزء الثاني كان يعطيك ملف access فيه Data جاهزة وطلب نسوي حوالي 10 او اكثر queries على الملف اللي عندنا ونرفعه. الملف اللي اعطانا كان معطينا اياه نفسه كاسايمنت من قبل.\n\n301 : نفس المياجر ، سهل الى متوسط\n\nالصوت:\nصوته ضعيييف، يحتاج تجلس قدام عشان تسمع صوته.\n\nإضافات :\nيعيب عليه لهجته خصوصا اول اسبوعين ثلاثة غالبا مب تفهم كلامه. من ناحية البونصات ففي 301 اعطانا خير من الله، في 101 اعطانا واجب عليه 3 درجات بونص.\nالدكتور متساهل ومتفهم جدًا جدًا للطالب. قبل كل اختبار يعطيك عناوين رئيسية عشان تراجعها ، وتجيك في الاختبار.\n\nبشكل عام انصح بالدكتور وبقوة في المواد العامة، مواد التخصص يحتاج يتطور شوي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510143-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jongtae-yu/180467/2", "user": "Jafar_15", "ts": 1558711436000, "tid": 180467, "pn": 2}}]}', 1558711436000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-delreystan-mis101', 'stk-delreystan', 'MIS 101', 'doc', '{"docs": [{"id": "stk-dr-f180467", "n": "Dr. Jongtae Yu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS101 - 191\nالتحضير : التحضير يكون عبارة عن ملف\\ملفين نرفعها للبلاكبورد بـ(كل) كلاس سواءً كنت حاضر أو لا، ماتقدر تعوضها اذا انتهى وقت الكلاس\nطريقة الشرح : أفرج، غالباً يركز على التطبيق ويعتبر مفيد بالكويزات والاختبارات لأن أغلبها عملية\n\nالكويزات : نفس تدريبات الكلاس لكن يغير الأرقام ، أفكارها واضحة وتعتبر سهلة إلى وسط\nالمياجر: ميد تيرم عملي على دروس الـ excel و الـfunctions حقه، يغطي كل شي درستوه حتى لو جابه بجزء من فقرة السؤال، الأفرج كان قريب ال20 من 25 (سهل-متوسط)\n\nالفاينلات : 30 درجة\\ 75 بوينت : كتابي وعملي،\nالجزء الكتابي: كان عن الSql وركز فيها أكثر من غيرها، multiple choice لـhtml من السلايدز الخاصة بها وسهلة وبديهية للي قرأها فقط\nالجزء العملي: تمارين عن برنامج Access ومأخوذة من الـlab assignments تركز على فهم الطالب للبرنامج\nبصفة عامة كان الحمدلله سهل وأغلب الطلاب خلصوا قبل الوقت بفترة\n\nالقريد النهائي: A يستاهل صراحة، اللي يميزه عن غيره أنه مخلص لعمله ويطبع هانداوتز للطلاب ويحاول يكون مثالي(بطريقة جيدة) ويرد عالايميل بسرعة ومتعاون ومايحاول يصعب المادة لأي طالب. ماعطيته A+ لأن عيبه الوحيد هو الصوت. أتمنى أنزل عنده مرة ثانية.\n\nالصوت: اكسنت كوري وصوت منخفض، احتجت اقعد قدام بعد أول كلاسين وبعض الطلاب ماكانوا فاهمين بسبب لدغة اللسان، شخصياً ماكانت عندي صعوبة بالفهم فقط بالسمع.\n\nإضافات : مايحب اللي ينقلوا ملفات التدريب وأعطى كم واحد 0 من 1.5 عالتمرين اللي نقله من طالب ثاني، حل بنفسك أو تذاكى وغير شوي بالملف المنقول 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517905-mis101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jongtae-yu/180467/4", "user": "delreystan", "ts": 1576126244000, "tid": 180467, "pn": 4}}]}', 1576126244000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
